method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    ensures result == class_name + "." + strongestExtension
    ensures strongestExtension in extensions
    ensures forall e: string :: e in extensions && strength(e) == maxStrength ==> e == strongestExtension
{
    var maxStrength := -infinity;
    var strongestExtension := "";

    // Iterate through each extension to calculate its strength
    var i: int;
    for i := 0 to extensions.Length - 1 {
        var extension := extensions[i];
        var strength := calculateStrength(extension);

        if strength > maxStrength {
            maxStrength := strength;
            strongestExtension := extension;
        }
    }

    result := class_name + "." + strongestExtension;
}

function calculateStrength(extension: string): int
{
    var cap := CountUppercase(extension);
    var sm := CountLowercase(extension);
    return cap - sm;
}

function CountUppercase(s: string): int
{
    var count := 0;
    var i: int;
    for i := 0 to s.Length - 1 {
        if char.IsUpper(s[i]) {
            count := count + 1;
        }
    }
    return count;
}

function CountLowercase(s: string): int
{
    var count := 0;
    var i: int;
    for i := 0 to s.Length - 1 {
        if char.IsLower(s[i]) {
            count := count + 1;
        }
    }
    return count;
}
